UPDATE businesses SET description = 'PNA Zambezi is a branch of the PNA stationery, books, arts and crafts, and educational-products retail chain, trading from Shop 12 in Zambesi Junction on Tibouchina Street, Montana Park. The store stocks a range spanning stationery supplies, books, arts and crafts materials, and educational products, serving students, parents, schools, teachers, artists, crafters and general retail customers from the surrounding Montana Park area. As part of the established PNA chain, the branch draws on the group''s broad product offering, giving local shoppers access to school and office stationery alongside craft supplies and reading material in one store. PNA Zambezi trades seven days a week, open Monday to Friday from 08:00 to 18:00, Saturday from 08:00 to 18:00, and Sunday from 08:00 to 16:00, giving customers wide access across the week whether they are stocking up for school terms, sourcing craft materials for a project, or picking up books and stationery items. Its location within Zambesi Junction places it conveniently for shoppers already visiting the centre, making it a practical stop for stationery, educational and creative supplies needs in the Montana Park area.', description_enriched_at = datetime('now') WHERE slug = 'pna-zambezi-montana-park' AND description = 'PNA Zambezi operates from the Zambezi Junction shopping centre in Montana Park, offering stationery, books and arts and crafts supplies as part of the PNA retail chain.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
